// JavaScript roadmap questions — set A (100): "predict the output / what does
// this do". 25 levels × 4. Combined with set B (lib/roadmap-questions.ts) this
// gives 8 questions per level. See lib/roadmap.ts for the per-level titles.

import type { Seed } from './roadmap-build';

export const jsSeedsA: Seed[] = [
  // ── Level 1 — Values & Math ────────────────────────────────────────────
  { q: 'What does this expression evaluate to?\n\n```js\n2 ** 3 + 1;\n```', opts: ['16', '9', '7', '6'], a: 1, e: '** has higher precedence than +, so 2 ** 3 is evaluated first and gives 8; adding 1 gives 9. 16 would need 2 ** (3 + 1), which the grammar never produces from this line, and 7 comes from reading ** as multiplication.', intro: 'Two operators, one expression. Decide which one JavaScript applies first, then do the other.', tags: ['Numbers', 'Operators'] , snippet: { version: 1, language: 'javascript', subtype: 'predict', objective: 'Operator precedence: exponentiation binds tighter than addition.' } },
  { q: 'A grid has 17 items and 5 columns. Which value is the number of items in the final incomplete row?\n\n```js\n17 % 5;\n```', opts: ['3', '2', '5', '3.4'], a: 1, e: '% returns the remainder of the division: 17 = 3 * 5 + 2, so the last partial row holds 2 items. 3 is the count of full rows (Math.floor(17 / 5)) and 3.4 is 17 / 5 itself; % returns neither.', intro: 'Splitting 17 into rows of 5 gives you two numbers: whole rows and what is left. Decide which one % returns.', tags: ['Numbers', 'Operators'] , snippet: { version: 1, language: 'javascript', subtype: 'predict', objective: 'The remainder operator, read as the leftover of an integer division.' } },
  { q: 'What does this evaluate to?\n\n```js\ntypeof 42;\n```', opts: ['"number"', '"integer"', '"42"', '"NaN"'], a: 0, e: 'typeof produces a string naming the type, so the result is "number", not the value 42. JavaScript has a single numeric type, so "integer" is not among typeof\'s results; "NaN" is a value, never a type name.', intro: 'typeof answers with a type name, not with the value. Ask whether JavaScript\'s type names separate whole numbers from decimals.', tags: ['typeof', 'Numbers'] , snippet: { version: 1, language: 'javascript', subtype: 'predict', objective: 'typeof returns a string, and every JS number shares one type.' } },
  { q: 'What does this evaluate to?\n\n```js\nMath.max(...[1, 5, 3]);\n```', opts: ['1', '3', '5', 'NaN'], a: 2, e: 'The spread passes three separate arguments, 1, 5 and 3, so Math.max returns the largest, 5. Without the dots, Math.max([1, 5, 3]) receives one array, converts it to a number and returns NaN, which is why NaN is on the list.', intro: 'Work out what the three dots hand to Math.max before deciding what it compares.', tags: ['Math', 'Numbers'] , snippet: { version: 1, language: 'javascript', subtype: 'predict', objective: 'Spread turns one array into separate arguments.' } },

  // ── Level 2 — Strings ──────────────────────────────────────────────────
  { q: 'What does this evaluate to?\n\n```js\n"hello".slice(1).length;\n```', opts: ['3', '4', '5', '6'], a: 1, e: 'slice(1) starts at index 1 and returns "ello", which has 4 characters. 5 is the length of the original "hello", which is what you get if you count before the slice; slice returns a new string and leaves "hello" unchanged.', intro: 'Two steps: work out the string slice(1) produces, then count that string, not the original.', tags: ['Strings'] , snippet: { version: 1, language: 'javascript', subtype: 'trace', objective: 'Chained string methods, each acting on the previous result.' } },
  { q: 'What does the method chain return?\n\n```js\n"Abc".toUpperCase().slice(1);\n```', opts: ['"bc"', '"BC"', '"ABC"', '"Bc"'], a: 1, e: 'toUpperCase runs first and returns "ABC"; slice(1) then drops the first character, giving "BC". "bc" is what slicing alone gives, with the uppercase step left out; strings are immutable, so neither call changes "Abc" itself.', intro: 'Only one of these two calls sees the original "Abc". Work out what it hands to the other before choosing.', tags: ['Strings', 'Methods'] , snippet: { version: 1, language: 'javascript', subtype: 'trace', objective: "Method chaining order: the second call sees the first call's output." } },
  { q: 'What is the result?\n\n```js\n"hello".slice(1, 3);\n```', opts: ['"he"', '"ell"', '"el"', '"llo"'], a: 2, e: 'slice(1, 3) copies from index 1 up to but not including index 3, so it returns "el" — two characters, 3 - 1. "ell" is what an inclusive end index would give, and "he" is the first two characters, taken from the start of the string instead of from index 1.', intro: 'slice takes a start index and an end index. Decide whether the character at the end index is part of the result.', tags: ['Strings', 'Methods'] },
  { q: 'How does split represent the missing value between two commas?\n\n```js\n"a,,c".split(",");\n```', opts: ['["a", "", "c"]', '["a", "c"]', '["a,,c"]', '["a", null, "c"]'], a: 0, e: 'split cuts the string at each separator, so the gap between the two adjacent commas becomes an empty string and the array has three elements. split never drops empty fields, which is what ["a", "c"] assumes, and never substitutes null for one. The same rule makes "a,b,".split(",") end with an empty string.', intro: 'The two commas sit next to each other with nothing between them. Decide what split puts in that gap.', tags: ['Strings', 'Arrays'] },

  // ── Level 3 — Booleans & Comparison ────────────────────────────────────
  { q: 'What does this return?\n\n```js\n1 === "1";\n```', opts: ['true', 'false', 'undefined', 'Error'], a: 1, e: '=== is strict equality and does not convert types. A number and a string are never strictly equal.', intro: 'The two sides are different types. Recall whether this particular operator is allowed to convert one of them first.', tags: ['Comparison', 'Equality'] },
  { q: 'What does this return?\n\n```js\n1 == "1";\n```', opts: ['true', 'false', 'undefined', 'Error'], a: 0, e: '== performs type coercion, converting "1" to the number 1 before comparing, so the result is true. === skips that conversion, which is why 1 === "1" is false and === is the safer default.', intro: 'One side is text and the other a number. Recall what == does about that mismatch before it compares.', tags: ['Comparison', 'Coercion'] },
  { q: 'What does this evaluate to?\n\n```js\n3 > 2 > 1;\n```', opts: ['true', 'false', '1', 'Error'], a: 1, e: 'It evaluates left to right: (3 > 2) is true, then true > 1 becomes 1 > 1, which is false. Reading it as a range check, the way mathematics writes 3 > 2 > 1, is what makes true tempting; JavaScript has no chained comparison.', intro: 'Work out the leftmost comparison on its own, then decide what the second comparison receives as its left operand.', tags: ['Comparison', 'Gotchas'] },
  { q: 'What is returned after the failed number conversion?\n\n```js\nBoolean(Number("not a number"));\n```', opts: ['true', 'false', 'NaN', 'undefined'], a: 1, e: 'Number("not a number") cannot parse the text and produces NaN, and NaN is one of JavaScript\'s falsy values, so Boolean returns false. Boolean never returns NaN — it always answers true or false — which is why the NaN option is wrong even though NaN is the intermediate value.', intro: 'Two steps. Decide what Number produces from text it cannot parse, then decide how Boolean treats that value.', tags: ['Booleans', 'Coercion'] },

  // ── Level 4 — Arrays: Basics ───────────────────────────────────────────
  { q: 'What is the array length after assigning index 2?\n\n```js\nconst items = [];\nitems[2] = "x";\nitems.length;\n```', opts: ['2', '3', '1', 'undefined'], a: 1, e: 'length is always one more than the highest index in use, so assigning index 2 makes it 3. Only one value was stored: indexes 0 and 1 are holes, not undefined values, which is why 1 feels right but is not what length reports. forEach and map skip holes, so a sparse array of length 3 can iterate once.', intro: 'Ask what length is derived from: the number of values you stored, or the position you stored them at.', tags: ['Arrays'] },
  { q: 'What does indexOf return when the value has a different type?\n\n```js\n[1, 2, 3].indexOf("2");\n```', opts: ['1', '-1', '2', 'undefined'], a: 1, e: 'indexOf compares with strict equality, so the string "2" never matches the number 2 and the result is -1. That -1 is a \'not found\' signal, not a position, so if (list.indexOf(x)) is wrong twice over: -1 is truthy and index 0 is falsy. Values that arrive from forms or query strings are strings, which is how this bug reaches production.', intro: 'The array holds numbers and the argument is text. Recall which kind of equality indexOf uses before deciding whether they match.', tags: ['Arrays', 'Methods'] },
  { q: 'What does includes return when the value has a different type?\n\n```js\n[1, 2, 3].includes("2");\n```', opts: ['true', 'false', '-1', 'undefined'], a: 1, e: 'includes compares with SameValueZero, which converts nothing, so the string "2" does not match the number 2 and the result is false. includes always answers with a boolean; -1 belongs to indexOf. The one difference from strict equality is NaN: [NaN].includes(NaN) is true while [NaN].indexOf(NaN) is -1.', intro: 'The array holds numbers and the argument is text. Also decide what shape of answer includes gives back.', tags: ['Arrays', 'Methods'] },
  { q: 'What does this return?\n\n```js\n["a", null, "b"].join("-");\n```', opts: ['"a-null-b"', '"a--b"', '"a-b"', '["a", "b"]'], a: 1, e: 'join converts null and undefined to empty text but still writes a separator on each side, so the result is "a--b" with an empty middle field. "a-null-b" is what stringifying first would give (["a", null, "b"].map(String).join("-")), and "a-b" assumes join drops the element, which it never does.', intro: 'null is not skipped. Decide what text stands in its place and how many separators survive.', tags: ['Arrays', 'Methods'] },

  // ── Level 5 — Objects: Basics ──────────────────────────────────────────
  { q: 'What does the computed property access return?\n\n```js\nconst key = "a";\nconst o = { a: 1 };\no[key];\n```', opts: ['1', 'undefined', '"a"', 'Error'], a: 0, e: 'Brackets evaluate what is inside them, so o[key] becomes o["a"] and reads 1. Dot access does not: o.key would look for a property literally named key, which the object does not have, giving undefined. Bracket notation is therefore how you read a property whose name is only known while the program runs.', intro: 'Decide whether the brackets use the variable\'s value or the word written between them.', tags: ['Objects'] },
  { q: 'What does this return?\n\n```js\nObject.keys({ a: 1, b: 2 });\n```', opts: ['["a", "b"]', '[1, 2]', '["a:1", "b:2"]', '2'], a: 0, e: 'Object.keys returns an array of the object\'s own enumerable property names, so ["a", "b"] — the names as strings, not the values and not a count. Object.values would give [1, 2] and Object.entries the pairs. Keys come back in insertion order, except that integer-like keys are listed first in ascending order.', intro: 'Decide which half of each name-value pair Object.keys collects, and what container it hands back.', tags: ['Objects', 'Methods'] },
  { q: 'What is the result?\n\n```js\nconst o = {};\no.x;\n```', opts: ['null', 'undefined', 'Error', '0'], a: 1, e: 'Reading a property that was never set gives undefined, and no error is raised for a missing property on an object. null is different: it is a value someone assigns deliberately, so it never appears on its own. The familiar crash comes one step later — o.x.y throws TypeError because it reads a property of undefined.', intro: 'Nothing was ever stored under x. Recall what JavaScript hands back in that case, rather than what a stricter language would do.', tags: ['Objects'] },
  { q: 'What does this return?\n\n```js\nObject.values({ a: 1, b: 2 });\n```', opts: ['["a", "b"]', '[1, 2]', '{ a: 1, b: 2 }', '2'], a: 1, e: 'Object.values returns an array of the property values in the same order Object.keys reports the names, so [1, 2]. ["a", "b"] is what Object.keys returns, and 2 is the count you would get from Object.keys(o).length. Use values when only the data matters, for example summing amounts.', intro: 'The object has two properties. Ask whether values gives you the names or what the names point to.', tags: ['Objects', 'Methods'] },

  // ── Level 6 — Array Iteration (map/forEach) ────────────────────────────
  { q: 'What does this return?\n\n```js\n[1, 2, 3].map(x => x * 2);\n```', opts: ['[1, 2, 3]', '[2, 4, 6]', '6', '[1, 4, 9]'], a: 1, e: 'map calls the callback for every element and collects the returned values into a new array of the same length, so doubling gives [2, 4, 6]. It never collapses the array to one value — 6 would come from a sum with reduce — and it does not change the original, which still reads [1, 2, 3].', intro: 'The arrow runs once per element. Decide what map does with each value the arrow returns.', tags: ['Arrays', 'map'] },
  { q: 'map passes both the value and index. What is the result?\n\n```js\n[1, 2, 3].map((value, index) => value + index);\n```', opts: ['[1, 3, 5]', '[1, 2, 3]', '[0, 1, 2]', '[2, 4, 6]'], a: 0, e: 'The callback adds indexes 0, 1, and 2 to the corresponding values, producing [1, 3, 5].', tags: ['Arrays', 'map'] },
  { q: 'What is the value of r?\n\n```js\nconst r = [1, 2].forEach(x => x);\nr;\n```', opts: ['[1, 2]', 'undefined', '2', '[undefined, undefined]'], a: 1, e: 'forEach always returns undefined: it exists for side effects, so the callback\'s return value is discarded rather than collected. r is therefore undefined — not [1, 2], and not [undefined, undefined], since nothing is collected at all. map is the method that builds an array from callback results, which is also why forEach cannot be chained.', intro: 'The arrow returns each value, but ask what forEach itself hands back to r.', tags: ['Arrays', 'forEach'] },
  { q: 'What does this return?\n\n```js\n["a", "b", "c"].map((x, i) => i);\n```', opts: ['[0, 1, 2]', '["a", "b", "c"]', '[1, 2, 3]', '3'], a: 0, e: 'The second parameter of a map callback is the element\'s index, starting at 0, so the result is [0, 1, 2]. [1, 2, 3] would be 1-based positions, which JavaScript never uses, and map returns a new array of the same length rather than the count 3.', intro: 'The callback ignores its first parameter. Recall what the second one holds and where it starts counting.', tags: ['Arrays', 'map'] },

  // ── Level 7 — filter & find ────────────────────────────────────────────
  { q: 'What does this return?\n\n```js\n[1, 2, 3, 4].filter(x => x % 2 === 0);\n```', opts: ['[2, 4]', '[1, 3]', '[1, 2, 3, 4]', '2'], a: 0, e: 'filter keeps every element whose callback returns true, so the even numbers survive and the result is the array [2, 4]. [1, 3] is the elements that fail the test. filter always returns an array, even when one element or none matches: a bare 2 would come from find, and a count from .length.', intro: 'Run x % 2 === 0 over each number in turn, then decide what filter does with the ones that pass.', tags: ['Arrays', 'filter'] },
  { q: 'What does this return?\n\n```js\n[1, 2, 3, 4].find(x => x > 2);\n```', opts: ['3', '[3, 4]', '4', 'undefined'], a: 0, e: 'find returns the first element that satisfies the test and stops scanning, so the result is the number 3, not an array. [3, 4] is what filter would return, and undefined is what find gives only when no element matches — which is why its result has to be checked before it is used.', intro: 'find stops at the first element that passes. Decide which element that is, and whether it comes back wrapped in anything.', tags: ['Arrays', 'find'] },
  { q: 'What is the result?\n\n```js\n[1, 2, 3].filter(x => x > 5);\n```', opts: ['[]', 'undefined', '[1, 2, 3]', 'null'], a: 0, e: 'filter builds a new array from the elements that pass the test. None of 1, 2, 3 is greater than 5, so the new array is empty: []. It is never undefined (that is what find returns when nothing matches) or null, and the original array is neither returned nor changed. Remember that [] is truthy, so check result.length rather than the array itself.', intro: 'Apply the test x > 5 to each element, then ask what kind of value filter returns no matter how many elements pass.', tags: ['Arrays', 'filter'] },
  { q: 'What does this return?\n\n```js\n[5, 12, 8, 130].find(x => x > 10);\n```', opts: ['12', '130', '[12, 130]', '5'], a: 0, e: 'find walks the array in order and returns the first element for which the callback is true; 12 is the first value above 10, so the search stops there. [12, 130] is what filter would return, and 130 would need a \'largest match\' rule that find does not have. If nothing matched, find would return undefined rather than an empty array.', intro: 'find and filter answer different questions — one element or all matches. Decide which this is, then apply x > 10 in array order.', tags: ['Arrays', 'find'] },

  // ── Level 8 — reduce ───────────────────────────────────────────────────
  { q: 'What does this return?\n\n```js\n[1, 2, 3, 4].reduce((a, b) => a + b, 0);\n```', opts: ['10', '24', '[1, 2, 3, 4]', '0'], a: 0, e: 'reduce starts the accumulator at the initial value 0 and calls the callback once per element: 0+1 = 1, 1+2 = 3, 3+3 = 6, 6+4 = 10. The final accumulator, 10, is the result. 24 would be the product, not the sum, and reduce never returns the original array; 0 is only the starting value.', intro: 'Follow the accumulator a: it starts at the second argument to reduce, and each callback result becomes the next a.', tags: ['Arrays', 'reduce'] },
  { q: 'What is the result?\n\n```js\n[1, 2, 3].reduce((a, b) => a * b, 1);\n```', opts: ['6', '7', '0', '9'], a: 0, e: 'The accumulator starts at 1 and is multiplied by each element in turn: 1×1 = 1, 1×2 = 2, 2×3 = 6, so the result is 6. Adding instead of multiplying would give 1+1+2+3 = 7, and 9 comes from mixing the two ((1+2)×3). 0 appears only if the initial value were 0 — a common slip when copying the sum pattern — because anything multiplied by 0 stays 0. An initial value of 1 is the identity for multiplication, just as 0 is for addition.', intro: 'The initial value here is 1, not 0; multiply it through the array one element at a time and keep the running product.', tags: ['Arrays', 'reduce'] },
  { q: 'What does this return?\n\n```js\n["a", "b", "c"].reduce((a, b) => a + b, "");\n```', opts: ['"abc"', '["a", "b", "c"]', '"cba"', '"a,b,c"'], a: 0, e: 'With \'\' as the initial value, the accumulator is a string from the start: \'\' + \'a\' = \'a\', \'a\' + \'b\' = \'ab\', \'ab\' + \'c\' = \'abc\'. reduce visits elements left to right, so \'cba\' would need reduceRight, and no separator is inserted, so \'a,b,c\' (the default join() output) is wrong. The result is a string, not the original array. In practice arr.join(\'\') does this job directly; the point here is that the seed can be any type, and the accumulator takes that type.', intro: 'The accumulator starts as an empty string; write out a + b after each of the three callback calls, keeping the order the array gives.', tags: ['Arrays', 'reduce'] },
  { q: 'What is returned (no initial value)?\n\n```js\n[1, 2, 3].reduce((a, b) => a + b);\n```', opts: ['6', '5', '7', 'Error'], a: 0, e: 'Without an initial value, reduce uses the first element (1) as the starting accumulator and begins the callback at the second: 1+2 = 3, then 3+3 = 6. The answer 5 comes from dropping the first element entirely instead of using it as the seed. An error is raised only when the array is empty and there is no initial value — TypeError: Reduce of empty array with no initial value — which is the practical reason to pass an initial value for lists that may be empty.', intro: 'With no second argument, reduce has to take its starting accumulator from the array itself; work out which element that is and where the first callback call begins.', tags: ['Arrays', 'reduce'] },

  // ── Level 9 — Destructuring ────────────────────────────────────────────
  { q: 'What is the value of a?\n\n```js\nconst [a, b] = [1, 2];\na;\n```', opts: ['1', '2', '[1, 2]', 'undefined'], a: 0, e: 'Array destructuring assigns by position: a takes index 0 (1) and b takes index 1 (2). a is a single element, not the whole array [1, 2], and it would be undefined only if the array had no element at that position. The same positional rule is what makes const [state, setState] = useState(0) work.', intro: 'Read the brackets on the left as a pattern rather than a new array; decide how each name inside it is matched to the values on the right.', tags: ['Destructuring', 'Arrays'] },
  { q: 'What is the value of x?\n\n```js\nconst { x } = { x: 10, y: 20 };\nx;\n```', opts: ['10', '20', '{ x: 10 }', 'undefined'], a: 0, e: 'const { x } = obj reads obj.x into a new variable x, so x is 10. y is simply not extracted, and the pattern produces the value, not a sub-object { x: 10 }. x would be undefined only if the object had no property named x. Unlike array destructuring, the order of properties on the right-hand side does not matter.', intro: 'The braces on the left are a pattern, not a new object; decide how the name x is matched against the object on the right and what x then holds.', tags: ['Destructuring', 'Objects'] },
  { q: 'What is the value of c?\n\n```js\nconst [a, , c] = [1, 2, 3];\nc;\n```', opts: ['2', '3', 'undefined', '[1, 3]'], a: 1, e: 'The pattern [a, , c] has three positions; the empty middle slot consumes index 1 without binding it, so c receives index 2, which is 3. Answering 2 treats the hole as if it did not exist. c is not undefined because the array has a third element, and destructuring never bundles elements into [1, 3]. Holes are handy for skipping the full-match entry of a regex result, though naming the slot is often clearer to read.', intro: 'Count the commas in the pattern, then decide whether the empty slot between them is skipped over or still lines up with an element of the array.', tags: ['Destructuring', 'Arrays'] },
  { q: 'What is the value of a?\n\n```js\nconst { a = 5 } = {};\na;\n```', opts: ['undefined', '5', '0', 'Error'], a: 1, e: 'The default in { a = 5 } is used when the matched value is undefined, which is the case for a missing property, so a becomes 5 instead of undefined. Nothing throws: destructuring a missing property is fine; only destructuring null or undefined itself would throw a TypeError. The default is skipped for other falsy values — { a: 0 } would give 0 and { a: null } would give null — which is the same rule as default parameters.', intro: 'The right-hand object has no property a; decide what the = 5 in the pattern is for in exactly that case.', tags: ['Destructuring', 'Defaults'] },

  // ── Level 10 — Spread & Rest ───────────────────────────────────────────
  { q: 'What does this return?\n\n```js\n[...[1, 2], ...[3, 4]];\n```', opts: ['[1, 2, 3, 4]', '[[1, 2], [3, 4]]', '[4, 6]', '[1, 2, [3, 4]]'], a: 0, e: 'Spread copies the elements of each array into the surrounding literal, so the result is a single flat array [1, 2, 3, 4]. Without the dots, [[1, 2], [3, 4]] would be the nested result; the dots are what unpack each array. Both spreads behave the same, so [1, 2, [3, 4]] is wrong, and nothing is added element-wise. This is the common way to concatenate arrays without mutating either, equivalent to [1, 2].concat([3, 4]).', intro: 'The dots are applied to each inner array on its own; decide whether they leave that array as a single element or move its elements into the outer literal, and apply the same rule twice.', tags: ['Spread', 'Arrays'] },
  { q: 'What is the result?\n\n```js\nconst o = { ...{ a: 1 }, ...{ b: 2 } };\no;\n```', opts: ['{ a: 1, b: 2 }', '{ a: 1 }', '{ b: 2 }', 'TypeError'], a: 0, e: 'Each ... copies the own enumerable properties of its source into the new object, so o has both keys: { a: 1, b: 2 }. Neither source replaces the other because their keys differ. No error is thrown — object spread does not need an iterable, unlike array spread, where [...{ a: 1 }] throws a TypeError. The copy is shallow: nested objects are shared, not cloned.', intro: 'Two plain objects are spread into one literal; decide whether object spread accepts a non-iterable source at all and, if it does, whether the second source replaces or joins the first.', tags: ['Spread', 'Objects'] },
  { q: 'What does this return?\n\n```js\nfunction f(...args) {\n  return args.length;\n}\nf(1, 2, 3);\n```', opts: ['3', '1', '[1, 2, 3]', 'undefined'], a: 0, e: 'A rest parameter gathers all remaining arguments into a real array, so args is [1, 2, 3] and args.length is 3. The function returns the length, not the array itself. 1 would mean only the first argument was captured, and undefined would mean args had no length — but rest parameters are always arrays, even with no arguments (then length is 0). This replaces the older arguments object, which is array-like but has no array methods.', intro: '...args in a parameter list is a rest parameter; decide what type args is and how many items it holds for f(1, 2, 3).', tags: ['Rest', 'Functions'] },
  { q: 'What is the value of rest?\n\n```js\nconst [first, ...rest] = [1, 2, 3, 4];\nrest;\n```', opts: ['[2, 3, 4]', '[1]', '[1, 2, 3, 4]', '4'], a: 0, e: 'first takes index 0, and ...rest collects everything after it into a new array: [2, 3, 4]. rest is always an array — never a single element such as 4 — and it excludes elements already bound, so [1, 2, 3, 4] and [1] are wrong. The original array is untouched. This head/tail split is a common way to peel off the first element without mutating the source.', intro: 'first and ...rest divide the array between them; decide which elements each name receives and whether rest holds them one at a time or together in one value.', tags: ['Rest', 'Destructuring'] },

  // ── Level 11 — Functions & Scope ───────────────────────────────────────
  { q: 'What does this return?\n\n```js\nconst sq = x => x * x;\nsq(4);\n```', opts: ['8', '16', 'undefined', 'NaN'], a: 1, e: 'An arrow function whose body is a single expression (no braces) returns that expression\'s value, so sq(4) evaluates 4 * 4 and returns 16. undefined would be the result only with a block body that lacks return — const sq = x => { x * x; } — a common slip when converting between the two forms. 8 is x + x rather than x * x, and NaN would need x to be missing.', intro: 'There is no return keyword here; decide whether an arrow\'s concise body still produces a value, then do the arithmetic.', tags: ['Functions', 'Arrow'] },
  { q: 'What is the result?\n\n```js\nfunction g(a, b = 2) {\n  return a + b;\n}\ng(3);\n```', opts: ['3', '5', 'NaN', 'Error'], a: 1, e: 'g(3) supplies a only, so b is undefined at call time and the default b = 2 applies: 3 + 2 = 5. Without the default, 3 + undefined would be NaN, which is the bug default parameters exist to prevent. Passing fewer arguments than parameters is never an error in JavaScript. The default also applies when undefined is passed explicitly, but not for null: g(3, null) gives 3.', intro: 'Only one argument is passed; look at what the parameter list says should happen to b in that case.', tags: ['Functions', 'Defaults'] },
  { q: 'What is the value of x?\n\n```js\nlet x = 1;\n{\n  let x = 2;\n}\nx;\n```', opts: ['1', '2', 'undefined', 'Error'], a: 0, e: 'let x = 2 inside the braces declares a new, block-scoped variable that shadows the outer x only inside that block. When the block ends, the inner variable is gone and the outer x is still 1. Declaring a same-named let in an inner block is legal, so there is no error; a SyntaxError would occur only if the second let x were in the same block. With var instead of let, both lines would refer to one function-scoped variable and x would be 2.', intro: 'Two declarations use the same name; decide whether the braces create a separate scope for the inner let or whether both lines touch one variable.', tags: ['Scope', 'let'] },
  { q: 'What does h() return?\n\n```js\nfunction h() {\n  const x = 5;\n}\nh();\n```', opts: ['5', 'undefined', 'null', 'Error'], a: 1, e: 'h declares a local x but never returns anything, so the call h() evaluates to undefined. Local variables are not implicitly returned, so 5 is wrong, and JavaScript uses undefined — not null — as the \'no value\' result of a function. Nothing throws. A missing return (or an arrow with braces but no return) is a common reason undefined shows up in callers.', intro: 'Look for a return statement in h; then recall what a call expression evaluates to when the function finishes without one.', tags: ['Functions'] },

  // ── Level 12 — Closures ────────────────────────────────────────────────
  { q: 'What does the final inc() return?\n\n```js\nfunction counter() {\n  let c = 0;\n  return () => ++c;\n}\nconst inc = counter();\ninc();\ninc();\ninc();\n```', opts: ['1', '2', '3', 'undefined'], a: 2, e: 'counter() runs once and creates a single c; the arrow it returns keeps a reference to that same c, so each inc() call increments it in place: 1, 2, then 3. The final call returns 3. The value 1 would mean c was recreated for every call, which happens only if you call counter() again — a second counter() starts its own independent c at 0. ++c returns the incremented value, so it is never undefined.', intro: 'All three calls go through the same returned function; decide whether they see one shared c or a fresh c each time, then count.', tags: ['Closures'] },
  { q: 'What is returned?\n\n```js\nfunction makeAdder(x) {\n  return y => x + y;\n}\nconst add5 = makeAdder(5);\nadd5(3);\n```', opts: ['5', '3', '8', '53'], a: 2, e: 'makeAdder(5) returns a function that still has access to x = 5 through its closure; calling it with y = 3 evaluates 5 + 3 = 8. add5 does not return x or y alone, and both are numbers, so there is no string concatenation (\'53\'). Each makeAdder call creates its own x, so makeAdder(10) would give an independent adder. This \'function factory\' pattern is how you preset configuration for later calls.', intro: 'makeAdder(5) has already run; decide what x is inside the function it returned before add5(3) is evaluated.', tags: ['Closures'] },
  { q: 'What does outer()() return?\n\n```js\nfunction outer() {\n  let v = "a";\n  function inner() {\n    return v;\n  }\n  v = "b";\n  return inner;\n}\nouter()();\n```', opts: ['"a"', '"b"', 'undefined', 'Error'], a: 1, e: 'Closures capture variables, not snapshots of their values. inner is defined while v is \'a\', but v is reassigned to \'b\' before outer returns, and inner reads v only when it is finally called, so it returns \'b\'. \'a\' is the answer you get if you assume the value was copied at definition time. There is no error and v is not undefined, since it was declared and assigned before inner ran. The same rule explains why a callback registered earlier can see later changes to an outer variable.', intro: 'Decide whether inner captured the value of v at the moment it was defined or the variable v itself; then check what happened to v before outer returned.', tags: ['Closures'] },
  { q: 'What is the result?\n\n```js\nconst fns = [];\nfor (let i = 0; i < 3; i++) {\n  fns.push(() => i);\n}\nfns[0]() + fns[1]() + fns[2]();\n```', opts: ['0', '3', '6', '9'], a: 1, e: 'With let, each iteration of a for loop gets its own i binding, so the three arrows capture 0, 1 and 2 respectively and the sum is 3. With var instead, there would be one shared i that ends at 3 after the loop, every arrow would return 3, and the sum would be 9 — the classic closure-in-loop bug that let was designed to remove. 6 would need the values 1, 2, 3, and 0 would need every closure to see the initial i.', intro: 'This loop uses let; decide whether the three arrows share one i or each get their own, and what i is when each is called later.', tags: ['Closures', 'let'] },

  // ── Level 13 — Hoisting & let/const ────────────────────────────────────
  { q: 'What is logged?\n\n```js\nconsole.log(typeof x);\nvar x = 5;\n```', opts: ['"number"', '"undefined"', 'ReferenceError', '5'], a: 1, e: 'var declarations are hoisted to the top of their function or script and initialised to undefined; only the assignment x = 5 stays where it is. At the console.log line x already exists with the value undefined, so typeof x prints the string \'undefined\'. It is not a ReferenceError — that is what let or const would give here because of the temporal dead zone — and \'number\' would need the assignment to have run. This silent undefined is one of the main reasons to prefer let and const, which turn use-before-declaration into an error.', intro: 'typeof runs before the var line; decide whether the declaration or the assignment of x is moved to the top of the scope.', tags: ['Hoisting', 'var'] },
  { q: 'What happens?\n\n```js\nconsole.log(a);\nlet a = 5;\n```', opts: ['undefined', '5', 'ReferenceError', 'null'], a: 2, e: 'let and const declarations are hoisted to the top of their block but stay uninitialised until the declaration line runs — the temporal dead zone. Reading a before that line throws ReferenceError: Cannot access \'a\' before initialization. undefined is the var behaviour, where the binding is created and initialised early. The value 5 would need the declaration to have executed first, and null is never the default value of a variable. The error is deliberate: it turns a silent use-before-initialisation bug into a loud one.', intro: 'let is not var; decide whether a can be read on the lines above its declaration, and what the engine does when you try.', tags: ['Hoisting', 'let'] },
  { q: 'What happens?\n\n```js\nfoo();\nfunction foo() {\n  return 1;\n}\n```', opts: ['It returns 1', 'It throws a ReferenceError', 'It throws a TypeError', 'It returns undefined'], a: 0, e: 'Function declarations are hoisted in full — name and body — so foo is callable anywhere in its scope, including before the line where it appears, and foo() returns 1. A ReferenceError is what const foo = () => 1 would give when called early (temporal dead zone), and a TypeError is what var foo = function () {} would give, because foo would still be undefined at that point. The function has a return statement, so it does not return undefined. Relying on this hoisting is fine within a file, but declaring functions before use is easier to read.', intro: 'foo is declared with the function keyword, not assigned to a variable; decide when that declaration becomes available in its scope.', tags: ['Hoisting', 'Functions'] },
  { q: 'What happens?\n\n```js\nconst x = 1;\nx = 2;\n```', opts: ['2', '1', 'TypeError', 'undefined'], a: 2, e: 'A const binding cannot be reassigned; x = 2 throws TypeError: Assignment to constant variable. The assignment neither silently succeeds (2) nor is silently ignored (1) — it fails loudly at runtime. The restriction is on the binding only: a const object or array can still be mutated (const arr = []; arr.push(1) is fine), which is why \'const means immutable\' is a common misunderstanding. Reassignment needs let.', intro: 'const fixes the binding, not the value inside it; decide what the runtime does when the binding itself is assigned a second time.', tags: ['const'] },

  // ── Level 14 — this & Context ──────────────────────────────────────────
  { q: 'What does obj.get() return?\n\n```js\nconst obj = {\n  n: 5,\n  get() {\n    return this.n;\n  },\n};\nobj.get();\n```', opts: ['5', 'undefined', 'TypeError', 'null'], a: 0, e: 'When a function is called as obj.get(), the object before the dot becomes this for that call, so this.n reads obj.n, which is 5. For this.n to be undefined, this would have to be something other than obj, which happens only when the method is detached (const g = obj.get; g()) or written as an arrow function; neither applies here. There is no TypeError because this is a valid object.', intro: 'get is written with method shorthand and called as obj.get(). Ask what the part before the dot in that call does to this.', tags: ['this', 'Objects'] },
  { q: 'This code runs as a classic browser script (not a module). What does obj.get() return?\n\n```js\nconst obj = {\n  n: 5,\n  get: () => this.n,\n};\nobj.get();\n```', opts: ['5', 'undefined', 'TypeError', 'null'], a: 1, e: 'Arrow functions do not get their own this; they use the this of the scope in which they are written. That scope is the top level of the script, not obj, and in a classic browser script top-level this is the global object (window), which has no n, so the result is undefined. In an ES module top-level this is undefined and the same code throws a TypeError, which is why the script type matters. To read obj.n, write get() { return this.n; } instead.', intro: 'Arrow functions take this from the scope where they are written, not from how they are called. Ask which scope surrounds this object literal.', tags: ['this', 'Arrow'] },
  { q: 'What is the value of the last line?\n\n```js\nconst o = {\n  x: 1,\n  f() {\n    return this;\n  },\n};\no.f() === o;\n```', opts: ['true', 'false', 'undefined', 'Error'], a: 0, e: 'Calling f as o.f() sets this to the object before the dot, so f returns o itself and o.f() === o is true. It would be false if f had been extracted first (const g = o.f; g()), because then this would be undefined in strict mode or the global object in sloppy mode. The property x plays no part.', intro: 'Decide what this is inside f when the call is written o.f(), then check whether === compares that to the same object.', tags: ['this'] },
  { q: 'What does greet.call({ name: "Sam" }) return?\n\n```js\nfunction greet() {\n  return this.name;\n}\ngreet.call({ name: "Sam" });\n```', opts: ['"Sam"', 'undefined', 'TypeError', '{ name: "Sam" }'], a: 0, e: 'call invokes greet with its first argument as this, so this.name reads "Sam" from the object passed in. A plain greet() with no receiver would not have this set to that object: in strict mode this is undefined and this.name throws a TypeError, and in sloppy mode it reads name from the global object instead (window.name in a browser). call returns whatever the function returns, not the this object.', intro: 'Look at what the first argument of .call() becomes inside greet before you read this.name.', tags: ['this', 'call'] },

  // ── Level 15 — Callbacks & HOFs ────────────────────────────────────────
  { q: 'What is returned?\n\n```js\nfunction apply(fn, x) {\n  return fn(x);\n}\napply(n => n + 1, 9);\n```', opts: ['9', '10', 'undefined', 'TypeError'], a: 1, e: 'apply receives the arrow as fn and 9 as x, then evaluates fn(x), which is 9 + 1 = 10. 9 would mean fn was never applied, and undefined would need an arrow with a block body and no return; the expression body n + 1 returns implicitly. Naming the function apply does not clash with Function.prototype.apply, which is a method rather than a global, so there is no TypeError.', intro: 'Follow the two arguments: which one is the function, which one is handed to it, and what that function does with it.', tags: ['Callbacks', 'HOF'] },
  { q: 'What does this return?\n\n```js\n[1, 2, 3].map(String);\n```', opts: ['[1, 2, 3]', '["1", "2", "3"]', '"123"', 'TypeError'], a: 1, e: 'map calls String once per element with the element as its first argument, and String(1) is "1", so the result is ["1", "2", "3"]. "123" would need a join("") after the map; map always returns an array of the same length. Called as a plain function without new, String simply converts its argument, so there is no TypeError.', intro: 'String is passed as the callback, not called. Ask what String(value) returns for each element and what map collects.', tags: ['Callbacks', 'map'] },
  { q: 'What does h(3) return?\n\n```js\nconst compose = (f, g) => x => f(g(x));\nconst h = compose(a => a * 2, b => b + 1);\nh(3);\n```', opts: ['7', '8', '9', '6'], a: 1, e: 'compose(f, g) returns x => f(g(x)), so the right-hand function g runs first: 3 + 1 = 4, then f doubles it to 8. 7 is what you get by applying the functions in the opposite order, (3 * 2) + 1, and 6 skips g entirely. Compose applies its arguments right to left, which is why the order matters.', intro: 'compose returns x => f(g(x)). Decide which of the two arrows is g and runs first, then feed its result to f.', tags: ['HOF', 'Composition'] },
  { q: 'What does this return?\n\n```js\n[3, 1, 2].sort((a, b) => a - b);\n```', opts: ['[3, 1, 2]', '[1, 2, 3]', '[3, 2, 1]', '[1, 3, 2]'], a: 1, e: 'The comparator (a, b) => a - b returns a negative number when a is smaller than b, which tells sort to place a before b, so the array becomes [1, 2, 3]. b - a would give [3, 2, 1]. sort reorders the original array in place and returns it; use toSorted() when you need a copy.', intro: 'The comparator returns a - b. Recall what a negative result tells sort about the order of a and b.', tags: ['Arrays', 'sort'] },

  // ── Level 16 — Ternary & Short-circuit ─────────────────────────────────
  { q: 'What does this return?\n\n```js\n5 > 3 ? "yes" : "no";\n```', opts: ['"yes"', '"no"', 'true', '5'], a: 0, e: 'The ternary evaluates its condition first: 5 > 3 is true, so the whole expression becomes the value after the ?, which is "yes". The result is always one of the two branch values, never the condition\'s boolean, so true is wrong. "no" would be chosen only if the condition were false.', intro: 'Evaluate 5 > 3 first, then decide which of the two branch values the whole expression becomes.', tags: ['Ternary'] },
  { q: 'What is the result?\n\n```js\n0 || "fallback";\n```', opts: ['0', '"fallback"', 'true', 'false'], a: 1, e: '|| evaluates left to right and returns the first truthy operand; 0 is falsy, so it moves on and returns "fallback". It returns the operand itself, not a boolean, so true and false are wrong. Because || treats 0 and "" as missing, ?? is the better choice for defaults when 0 is a legitimate value.', intro: 'Decide first what kind of value || produces — a boolean, or one of its operands — and then whether 0 counts as truthy.', tags: ['Operators', 'Short-circuit'] },
  { q: 'What does this return?\n\n```js\n"hi" && "bye";\n```', opts: ['"hi"', '"bye"', 'true', 'false'], a: 1, e: '&& returns the first falsy operand, or the last operand when none is falsy. "hi" is truthy, so evaluation continues to "bye", which is returned as it is. Like ||, && yields an operand rather than a boolean, so true is wrong; "hi" would be returned only if it were the falsy one.', intro: 'Both operands are non-empty strings. Ask which operand && stops on when nothing along the way is falsy.', tags: ['Operators', 'Short-circuit'] },
  { q: 'What is the result?\n\n```js\nnull ?? "default";\n```', opts: ['null', '"default"', 'undefined', 'false'], a: 1, e: '?? returns the right-hand side only when the left is null or undefined; null qualifies, so the result is "default". Unlike ||, ?? leaves 0, "" and false untouched, which is what makes it the safer choice for defaults. The null on the left is replaced, not returned.', intro: '?? is not ||: it reacts to only two specific values. Check whether null is one of them.', tags: ['Operators', 'Nullish'] },

  // ── Level 17 — Type Coercion ───────────────────────────────────────────
  { q: 'What is the result?\n\n```js\n"5" + 3;\n```', opts: ['8', '"53"', '"8"', '53'], a: 1, e: 'When either operand of + is a string, + concatenates: 3 is converted to "3" and joined to "5", giving the string "53". 8 would require both operands to be numbers, and "8" would need numeric addition followed by a conversion that + never performs. This is the usual source of bugs with form input values, which are always strings.', intro: 'One operand is a string. Recall which job + does when either side is a string.', tags: ['Coercion', 'Strings'] },
  { q: 'What does this return?\n\n```js\n"5" - 3;\n```', opts: ['2', '"2"', '"53"', 'NaN'], a: 0, e: '- has no string meaning, so both operands are converted to numbers: "5" becomes 5 and 5 - 3 is the number 2, not the string "2". Only + concatenates, so "53" is wrong. NaN would appear only if the string could not be parsed as a number, such as "5px".', intro: 'Compare - with +: ask whether - has a string meaning at all, and what happens to "5" if it does not.', tags: ['Coercion', 'Numbers'] },
  { q: 'What is the result?\n\n```js\n1 + "2" + 3;\n```', opts: ['"123"', '6', '"15"', '"33"'], a: 0, e: '+ evaluates left to right. 1 + "2" involves a string, so it concatenates to "12"; then "12" + 3 concatenates again to "123". 6 would require all three operands to be numbers, and "33" would need 1 + 2 to be added first, which the left-to-right order does not allow. Compare 1 + 2 + "3", which gives "33".', intro: 'Evaluate strictly left to right: settle 1 + "2" first, then apply + to that result and 3.', tags: ['Coercion'] },
  { q: 'What does this return?\n\n```js\n[] + [];\n```', opts: ['0', '"[]"', '""', '[]'], a: 2, e: '+ converts objects to primitives first, and an array converts through toString, which joins its elements with commas; an empty array becomes "". "" + "" is "", so the result is an empty string — not 0, and not an array. "[]" is how a console displays an array, never what String([]) returns; the same rule is why [1, 2] + [3] gives "1,23".', intro: '+ turns objects into primitives first. Ask what String([]) gives for an empty array, then add two of them.', tags: ['Coercion', 'Gotchas'] },

  // ── Level 18 — Truthy / Falsy ──────────────────────────────────────────
  { q: 'What is the result?\n\n```js\nBoolean("");\n```', opts: ['true', 'false', '""', 'undefined'], a: 1, e: '"" is one of the falsy values, so Boolean("") is false. Boolean always returns true or false, never the input itself. The complete falsy list is false, 0, -0, 0n, "", null, undefined and NaN; every other value, including "0" and " ", is truthy.', intro: 'Boolean() applies the fixed falsy list. Ask whether an empty string is on it.', tags: ['Truthy', 'Booleans'] },
  { q: 'What does this return?\n\n```js\nBoolean("0");\n```', opts: ['true', 'false', '0', 'undefined'], a: 0, e: 'Truthiness of a string depends only on whether it is empty, not on what it contains. "0" has one character, so it is truthy and Boolean("0") is true. The number 0 is falsy, which is why form input values — always strings — need explicit conversion before a truthiness check.', intro: 'This is the string "0", not the number 0. Ask whether the falsy rule for strings looks at content or at length.', tags: ['Truthy', 'Gotchas'] },
  { q: 'What is the result?\n\n```js\nBoolean([]);\n```', opts: ['true', 'false', '[]', 'undefined'], a: 0, e: 'Every object is truthy, including an empty array and an empty object; truthiness never looks inside the value. Boolean([]) is therefore true. To test whether an array is empty, check arr.length === 0 — an if (arr) guard will always run.', intro: 'Truthiness for objects does not look inside them. Ask which category an empty array belongs to.', tags: ['Truthy', 'Arrays'] },
  { q: 'What does this return?\n\n```js\n!!null;\n```', opts: ['true', 'false', 'null', 'undefined'], a: 1, e: 'The first ! converts null to a boolean and negates it: !null is true. The second ! negates again, giving false, the same result as Boolean(null). The result of !! is always a boolean, so null and undefined are impossible outputs.', intro: 'A single ! converts to a boolean and flips it; the second flips it back. Ask what Boolean(null) is.', tags: ['Truthy', 'Operators'] },

  // ── Level 19 — JSON & Objects ──────────────────────────────────────────
  { q: 'What is the result?\n\n```js\nJSON.stringify({ a: 1 });\n```', opts: ['\'{"a":1}\'', '"{a:1}"', '"[object Object]"', '{ a: 1 }'], a: 0, e: 'JSON.stringify returns a string of JSON text: keys are always double-quoted and there is no whitespace by default, so the result is the string \'{"a":1}\'. "{a:1}" is not valid JSON because the key is unquoted. "[object Object]" is what String({ a: 1 }) gives; JSON.stringify does not use toString, and the result is text rather than the object itself.', intro: 'JSON.stringify produces text, not an object. Ask how JSON writes keys and whether the result is a string.', tags: ['JSON', 'Objects'] },
  { q: 'What does this return?\n\n```js\nJSON.parse("[1,2,3]");\n```', opts: ['"[1,2,3]"', '[1, 2, 3]', '{ 0: 1, 1: 2, 2: 3 }', 'Error'], a: 1, e: 'JSON.parse converts JSON text into a live JavaScript value; a JSON array becomes a real array, so the result is [1, 2, 3]. It is no longer a string, and a JSON array never becomes a plain object with numeric keys. An error would be thrown only for invalid JSON, such as a trailing comma or single quotes.', intro: 'JSON.parse goes from text to a live value. Ask what a JSON array turns into once it has been parsed.', tags: ['JSON', 'Arrays'] },
  { q: 'What is the result?\n\n```js\nObject.assign({}, { a: 1 }, { a: 2 });\n```', opts: ['{ a: 1 }', '{ a: 2 }', '{ a: 1, a: 2 }', '{}'], a: 1, e: 'Object.assign copies own enumerable properties from each source into the target, left to right, so { a: 2 } overwrites the a copied from { a: 1 } and the result is { a: 2 }. An object cannot hold the same key twice, so { a: 1, a: 2 } is impossible. Object.assign mutates and returns the target — here the fresh {} — which is why an empty first argument is used to avoid changing the sources.', intro: 'Object.assign copies sources into the target from left to right. Ask what happens when a later source has a key the target already received.', tags: ['Objects', 'Methods'] },
  { q: 'What is the value of a.x?\n\n```js\nconst a = { x: 1 };\nconst b = { ...a };\nb.x = 2;\na.x;\n```', opts: ['1', '2', 'undefined', 'Error'], a: 0, e: '{ ...a } creates a new object b with its own copy of x, so b.x = 2 writes to b\'s property and a.x stays 1. The copy is shallow, though: had x been a nested object, b.x.y = 2 would have changed a as well, because both objects would share the same nested reference. There is no error because b is an ordinary mutable object.', intro: 'Spreading a copies its properties into a new object b. Ask whether b.x = 2 writes into that new object or into a.', tags: ['Spread', 'Objects'] },

  // ── Level 20 — Optional Chaining & Nullish ─────────────────────────────
  { q: 'What is the result?\n\n```js\nconst u = { profile: null };\nu.profile?.name;\n```', opts: ['null', 'undefined', 'Error', '""'], a: 1, e: 'u.profile is null, so ?. short-circuits: the rest of the chain is skipped and the whole expression evaluates to undefined. Plain u.profile.name would throw a TypeError because null has no properties. A short-circuited chain always yields undefined, never null, even when the value that stopped it was null, and no empty string is involved.', intro: 'profile is present but holds null. Recall exactly what value the whole chain becomes when ?. meets null on its left side.', tags: ['Optional chaining'] },
  { q: 'What does this return?\n\n```js\nconst o = { a: { b: 2 } };\no.a?.b;\n```', opts: ['2', 'undefined', 'Error', 'null'], a: 0, e: 'o.a is an object, so ?. has nothing to short-circuit and behaves exactly like o.a.b, giving 2. Optional chaining changes the outcome only when the value before ?. is null or undefined; otherwise it reads the property as usual. undefined would need a to be missing (o.a?.b on {} gives undefined), a short-circuit never yields null, and the syntax is standard, so no error is thrown.', intro: 'Nothing to the left of ?. is null or undefined here. Work out what optional chaining does when there is nothing to guard against.', tags: ['Optional chaining'] },
  { q: 'What is the result?\n\n```js\nconst x = 0;\nx ?? 5;\n```', opts: ['0', '5', 'undefined', 'NaN'], a: 0, e: '?? returns its right-hand side only when the left side is null or undefined. 0 is a real number, so the expression keeps 0. The || operator would have given 5 because 0 is falsy, which is the trap ?? was added to avoid when 0, "" or false are legitimate values. Nothing is converted, so NaN and undefined do not appear.', intro: 'The left side is 0, which is falsy but not nullish. Decide which of those two properties ?? actually tests.', tags: ['Nullish'] },
  { q: 'What does this return?\n\n```js\nconst arr = null;\narr?.length;\n```', opts: ['0', 'null', 'undefined', 'Error'], a: 2, e: 'Optional chaining on null returns undefined rather than throwing.', tags: ['Optional chaining'] },

  // ── Level 21 — Promises ────────────────────────────────────────────────
  { q: 'What value does the resulting promise resolve to?\n\n```js\nPromise.resolve(5).then(v => v * 2);\n```', opts: ['5', '10', 'Promise', 'undefined'], a: 1, e: 'then receives the resolved value 5, runs v * 2, and the promise that then returns resolves to that result, 10. The original promise still holds 5, which is why chains transform values rather than mutate their source. The result is not a Promise object, because then unwraps the callback\'s return value, and it would be undefined only if the callback returned nothing.', intro: 'then hands v the settled value and builds a new promise from whatever the callback returns. Follow 5 through the arrow function.', tags: ['Promises'] },
  { q: 'What does the final promise resolve to?\n\n```js\nPromise.resolve(1).then(v => v + 1).then(v => v + 1);\n```', opts: ['1', '2', '3', 'Promise'], a: 2, e: 'Promise.resolve(1) settles with 1; the first then returns 2, so the promise it creates resolves to 2; the second then receives that 2 and returns 3. Each then reads the previous callback\'s return value, not the original 1, which is why 2 (only one step applied) is wrong. The chain\'s final value is a plain number, not a Promise object.', intro: 'Each then receives whatever the previous callback returned, not the original value. Carry the number through both steps.', tags: ['Promises', 'Chaining'] },
  { q: 'What is logged?\n\n```js\nasync function f() {\n  return 5;\n}\nconsole.log(typeof f());\n```', opts: ['"number"', '"object"', '"function"', '"promise"'], a: 1, e: 'An async function never hands back its raw return value: f() returns a Promise that will resolve to 5. typeof reports "object" for a Promise because there is no dedicated "promise" type tag; typeof only distinguishes primitives, functions and objects. "number" would require awaiting f() first, and "function" describes f itself (typeof f), not the result of calling it.', intro: 'Look at the async keyword before you look at the return statement. Ask what kind of value calling any async function hands back.', tags: ['Promises', 'async'] },
  { q: 'What does the promise resolve to?\n\n```js\nPromise.all([Promise.resolve(1), Promise.resolve(2)]);\n```', opts: ['[1, 2]', '1', '3', 'Promise'], a: 0, e: 'Promise.all takes an iterable of promises and resolves to a single array of their values in input order, [1, 2], once every input has fulfilled. It does not pick the first result (that is Promise.race, which would give 1) and it never combines values arithmetically. If any input rejected, the whole Promise.all would reject with that reason instead.', intro: 'all waits for every input promise before it settles. Think about how it has to package several results into one value.', tags: ['Promises'] },

  // ── Level 22 — Async / Await ───────────────────────────────────────────
  { q: 'What does f() resolve to?\n\n```js\nasync function f() {\n  const x = await Promise.resolve(7);\n  return x + 1;\n}\n```', opts: ['7', '8', 'Promise(8)', 'undefined'], a: 1, e: 'await Promise.resolve(7) suspends f until the promise settles and yields the plain number 7, so x + 1 is 8. Because f is async, calling it returns a Promise, and that promise resolves to 8. The question asks for the resolved value, so the answer is 8 rather than a Promise wrapping 8; 7 would mean the + 1 was skipped, and undefined would need a missing return.', intro: 'await gives x the settled value, not the promise. Then apply the return line and remember the question asks what f() resolves to.', tags: ['async', 'await'] },
  { q: 'What does g() resolve to?\n\n```js\nasync function f() {\n  return 1;\n}\nasync function g() {\n  const v = await f();\n  return v + 1;\n}\n```', opts: ['1', '2', '3', 'Promise'], a: 1, e: 'f() returns a Promise that resolves to 1. Inside g, await f() waits for it and yields the plain 1, so v + 1 is 2 and g() resolves to 2. Without the await, v would be a Promise and v + 1 would produce the string "[object Promise]1", which is the bug this pattern avoids; 3 would require adding 1 twice.', intro: 'f is async, so f() is a promise; await is what turns it back into a number. Then apply g\'s arithmetic.', tags: ['async', 'await'] },
  { q: 'In what order are values logged?\n\n```js\nconsole.log("A");\nsetTimeout(() => console.log("B"), 0);\nconsole.log("C");\n```', opts: ['A B C', 'A C B', 'C A B', 'B A C'], a: 1, e: 'console.log("A") runs, setTimeout only schedules B as a task for a later turn of the event loop, and console.log("C") runs immediately, so the synchronous output is A then C. Only after the call stack is empty does the event loop pick up the timer task and log B. A 0 ms delay is a minimum, not a guarantee of immediate execution, so A B C is wrong.', intro: 'Separate the code that runs synchronously from the callback handed to setTimeout, then ask what a timer\'s delay actually promises about when that callback runs.', tags: ['Event loop', 'async'] },
  { q: 'What happens when this code runs?\n\n```js\nasync function f() {\n  throw new Error("x");\n}\nf().catch(() => "caught");\n```', opts: ['The error is thrown synchronously and nothing catches it', 'f() returns a rejected promise and the .catch handler runs', 'f() returns undefined, so calling .catch throws a TypeError', 'throw inside an async function is a SyntaxError'], a: 1, e: 'Calling an async function always returns a promise; a throw inside the body rejects that promise rather than throwing synchronously, so f() itself does not throw. The .catch handler receives the Error and the chain fulfills with "caught". Nothing is uncaught, f() does not return undefined, and throw is ordinary syntax inside async functions.', intro: 'Think about what calling an async function always returns, and where a throw inside its body ends up.', tags: ['async', 'Errors'] },

  // ── Level 23 — Sets & Maps ─────────────────────────────────────────────
  { q: 'What is the value?\n\n```js\nnew Set([1, 1, 2, 3, 3]).size;\n```', opts: ['5', '3', '2', '4'], a: 1, e: 'The Set constructor adds each element of the array but ignores values already present, so the duplicates of 1 and 3 are dropped and the Set holds 1, 2 and 3: size is 3. The input array\'s length, 5, counts repeats, which a Set never does; 2 and 4 would need a different number of distinct values.', intro: 'size is not the length of the array you passed in. Ask what a Set keeps when the same value arrives twice.', tags: ['Set'] },
  { q: 'What does this return?\n\n```js\n[...new Set([1, 2, 2, 3])];\n```', opts: ['[1, 2, 2, 3]', '[1, 2, 3]', '3', '[1, 3]'], a: 1, e: 'new Set([1, 2, 2, 3]) keeps one copy of each value in insertion order, and spreading it into an array literal iterates those values, giving [1, 2, 3]; this is the usual one-liner for removing duplicates from an array. The result is an array, not the count 3, and a Set keeps one instance of a repeated value rather than removing it entirely, so [1, 3] is wrong. Array.from(set) does the same job.', intro: 'Two steps: what the Set keeps, and what spreading an iterable back into [] produces. Keep the original order in mind.', tags: ['Set', 'Spread'] },
  { q: 'What does m.get("a") return?\n\n```js\nconst m = new Map();\nm.set("a", 1);\nm.get("a");\n```', opts: ['1', '"a"', 'undefined', '{ a: 1 }'], a: 0, e: 'm.set("a", 1) stores the value 1 under the key "a", and m.get("a") looks up that key and returns the stored value, 1. get never returns the key itself or an object wrapper around the entry, and undefined would appear only for a key that was never set.', intro: 'set stores a pair; get looks up one side of that pair by the other. Decide which side you pass in and which you get back.', tags: ['Map'] },
  { q: 'What does this return?\n\n```js\nconst m = new Map([["x", 1]]);\nm.has("x");\n```', opts: ['true', 'false', '1', 'undefined'], a: 0, e: 'new Map([["x", 1]]) creates a map with one entry, key "x" and value 1. m.has("x") tests whether the key exists and returns a boolean, so the result is true. It would be 1 only with m.get("x"), and false or undefined would require a key that was never added.', intro: 'Look at what the constructor array put into the map, then remember what kind of answer has gives, as opposed to get.', tags: ['Map'] },

  // ── Level 24 — Edge Cases & Gotchas ────────────────────────────────────
  { q: 'What does this return?\n\n```js\n0.1 + 0.2 === 0.3;\n```', opts: ['true', 'false', '0.3', 'NaN'], a: 1, e: '0.1, 0.2 and 0.3 are all approximations in IEEE 754 binary floating point. The sum 0.1 + 0.2 evaluates to 0.30000000000000004, which is a different double from the literal 0.3, so === yields false. A comparison always produces a boolean, never 0.3 or NaN. When decimal fractions matter, compare with a tolerance such as Math.abs(a - b) < Number.EPSILON or work in integer units like cents.', intro: 'JavaScript numbers are binary doubles. Consider whether decimal fractions like 0.1 and 0.2 are represented exactly before you trust the arithmetic.', tags: ['Numbers', 'Gotchas'] },
  { q: 'What is the result?\n\n```js\ntypeof null;\n```', opts: ['"null"', '"object"', '"undefined"', '"number"'], a: 1, e: 'typeof null returns "object", a quirk from the first JavaScript implementation, where null\'s type tag matched objects; it was never fixed because too much code depends on it. There is no "null" result, and undefined is a different value with its own tag "undefined". In practice a typeof x === "object" guard must also check x !== null before touching properties, or use x === null directly.', intro: 'typeof does not have a tag for every primitive. Recall which value is the famous exception and what it reports instead.', tags: ['typeof', 'Gotchas'] },
  { q: 'What does this return?\n\n```js\n[1, 2, 3] + "";\n```', opts: ['"123"', '"1,2,3"', '"[1,2,3]"', '6'], a: 1, e: 'When + has a string operand, the array is converted with its toString method, which is the same as join(","), giving "1,2,3". JSON.stringify would produce "[1,2,3]" with brackets, but + never uses JSON. The elements are not concatenated without a separator and not summed, because the string operand forces string concatenation rather than addition.', intro: '+ with a string operand turns the array into a string first. Ask which conversion applies: JSON.stringify, join, or something else.', tags: ['Coercion', 'Arrays'] },
  { q: 'What is the result?\n\n```js\nNaN === NaN;\n```', opts: ['true', 'false', 'NaN', 'undefined'], a: 1, e: 'By the IEEE 754 rules JavaScript follows, NaN compares unequal to every value, including itself, so NaN === NaN is false (and NaN !== NaN is true). A comparison always yields a boolean, never NaN or undefined. To test for NaN use Number.isNaN(x) or Object.is(x, NaN), both of which return true; x === NaN never works.', intro: 'IEEE 754 defines how NaN compares with any number, including another NaN. Apply that rule before assuming a value must equal itself.', tags: ['Numbers', 'Gotchas'] },

  // ── Level 25 — Mixed Mastery ───────────────────────────────────────────
  { q: 'What does this return?\n\n```js\n[1, 2, 3, 4, 5].filter(x => x % 2).map(x => x * 10);\n```', opts: ['[10, 30, 50]', '[20, 40]', '[10, 20, 30, 40, 50]', '[1, 3, 5]'], a: 0, e: 'For these values, x % 2 is 1 for the odd numbers and 0 for the even ones; filter keeps elements for which the callback returns a truthy value, so 1, 3 and 5 survive and 2 and 4 (result 0) are dropped. map then multiplies each by 10: [10, 30, 50]. [20, 40] would need the opposite predicate, and [1, 3, 5] is the intermediate array before map.', intro: 'filter keeps elements whose callback result is truthy, and x % 2 is a number, not a boolean. Work out which numbers survive before you multiply.', tags: ['Arrays', 'Chaining'] },
  { q: 'What does this return?\n\n```js\nObject.entries({ a: 1, b: 2 }).map(([k, v]) => `${k}=${v}`);\n```', opts: ['["a=1", "b=2"]', '["a", "b"]', '[1, 2]', '"a=1,b=2"'], a: 0, e: 'Object.entries({ a: 1, b: 2 }) returns [["a", 1], ["b", 2]]. map destructures each pair into k and v and returns the template string, so the result is ["a=1", "b=2"]. Object.keys would give ["a", "b"] and Object.values [1, 2]; a single string "a=1,b=2" would need a .join(",") after the map.', intro: 'entries gives one two-element array per property. Follow how the destructured [k, v] fills the template, and remember map returns an array.', tags: ['Objects', 'map'] },
  { q: 'What does this return?\n\n```js\nconst arr = [1, 2, 3];\nconst doubled = arr.map(x => x * 2);\narr === doubled;\n```', opts: ['true', 'false', '[2, 4, 6]', 'undefined'], a: 1, e: 'map always allocates and returns a new array, leaving arr untouched, so arr and doubled are two different objects and === (which compares references, not contents) is false. It would be true only if map returned the original array, which it never does; methods like push or sort mutate in place instead. A comparison yields a boolean, so [2, 4, 6] is doubled\'s contents, not the result. This is why map is safe for immutable updates such as React state.', intro: '=== on two arrays compares identity, not contents. Ask whether map hands back the same array object or a fresh one.', tags: ['Arrays', 'Immutability'] },
  { q: 'What does this return?\n\n```js\n"hello world"\n  .split(" ")\n  .map(w => w[0].toUpperCase() + w.slice(1))\n  .join(" ");\n```', opts: ['"Hello World"', '"HELLO WORLD"', '"hello world"', '"Hello world"'], a: 0, e: 'split(" ") gives ["hello", "world"]; for each word, w[0].toUpperCase() + w.slice(1) uppercases only the first character and keeps the rest; join(" ") reassembles "Hello World". Both words are transformed because map runs the callback on every element, so "Hello world" is wrong, and only the first letter changes, so "HELLO WORLD" is wrong. Note that w[0] is undefined for an empty word, so an input with two consecutive spaces would throw.', intro: 'Three stages: what split produces, what the map callback does to each word, and what join puts back. Check whether the callback touches every word or only the first.', tags: ['Strings', 'Chaining'] },
];
